BEGIN TRANSACTION

CREATE TABLE #tt_geom (id int, label VARCHAR(50), gg GEOMETRY)
CREATE CLUSTERED INDEX cix ON #tt_geom(id)
SET NOCOUNT ON
DECLARE @g geometry =  'POLYGON((-121.97087 37.372518,-121.97087 37.372518,-121.970863 37.372517,-121.970845 37.372515,-121.97087 37.372518))'
DECLARE @donethislayer BIT = 0
DECLARE @showcolourmap BIT = 0
IF @showcolourmap = 1
BEGIN
	
 
	DECLARE @SSMSColourPalette table (idkey INT identity(1,1), id int, geom geometry)

	 DECLARE @x int = 0, @y int = 0;
	 WHILE @y < 30
	 BEGIN
	 WHILE @x < 30
	 BEGIN
	 INSERT INTO @SSMSColourPalette VALUES(
	 @y*10 + @x,
	 'POLYGON((' + cast(@x AS varchar(32)) + ' ' + cast(@y AS varchar(32)) + ','
	 + cast(@x + 1.5 AS varchar(32)) + ' ' + cast(@y AS varchar(32)) + ','
	 + cast(@x - 0.8 AS varchar(32)) + ' ' + cast(@y + 1 AS varchar(32)) + ','
	 + cast(@x AS varchar(32)) + ' ' + cast(@y + 1.5 AS varchar(32)) + ','
	 + cast(@x AS varchar(32)) + ' ' + cast(@y AS varchar(32)) + '))'
	 )
	 SET @x = @x + 1;
	 END
	 SET @x = 0;
	 SET @y = @y + 1;
	 END
	SELECT idkey, t.geom, t.id + 1 FROM @SSMSColourPalette t ORDER BY idkey asc;

END

DECLARE @i int = 1
WHILE @i <= 500
BEGIN
